export function authorizePaymentError(code: "timeout" | "declined") {
  if (code === "timeout") {
    return "Payment timed out";
  }
  return "Payment declined";
}

export function capturePaymentError(code: "timeout" | "failed") {
  if (code === "timeout") {
    return "Payment timed out";
  }
  return "Payment capture failed";
}
